def investigate(context, acquire):
    spans = acquire("spans")
    population = acquire("population")

    def span_union(intervals):
        if not intervals:
            return 0.0
        ordered = sorted(intervals)
        total = 0.0
        cur_start = ordered[0][0]
        cur_end = ordered[0][1]
        for start, end in ordered[1:]:
            if start > cur_end:
                total += cur_end - cur_start
                cur_start = start
                cur_end = end
            else:
                if end > cur_end:
                    cur_end = end
        total += cur_end - cur_start
        return total

    def span_elapsed(intervals):
        if not intervals:
            return 0.0
        lo = min(i[0] for i in intervals)
        hi = max(i[1] for i in intervals)
        return hi - lo

    def span_billed(intervals):
        return sum(i[1] - i[0] for i in intervals)

    contract = str(context.get("quantity_contract", "")).lower()
    if "billed" in contract:
        per_request = span_billed
    elif "elapsed" in contract or "first" in contract:
        per_request = span_elapsed
    else:
        per_request = span_union

    def period_requests(period):
        by_rid = {}
        for row in spans:
            if row["period"] != period:
                continue
            rid = row["rid"]
            by_rid.setdefault(rid, []).append((row["t0"], row["t1"]))
        return by_rid

    def request_class(period, rid):
        for row in spans:
            if row["period"] == period and row["rid"] == rid:
                return row["cohort"]
        return None

    def observed_counts(period):
        counts = {}
        for rid in period_requests(period):
            cls = request_class(period, rid)
            if cls is not None:
                counts[cls] = counts.get(cls, 0) + 1
        return counts

    def population_counts(period):
        counts = {}
        for row in population:
            if row["period"] == period:
                counts[row["class"]] = counts.get(row["class"], 0) + row["count"]
        return counts

    def duplicate_delivery():
        seen = set()
        for row in spans:
            key = (row["period"], row["rid"], row["sid"], row["t0"], row["t1"])
            if key in seen:
                return True
            seen.add(key)
        return False

    def conflicting_event():
        by_sid = {}
        for row in spans:
            key = (row["period"], row["rid"], row["sid"])
            val = (row["t0"], row["t1"])
            if key in by_sid:
                if by_sid[key] != val:
                    return True
            else:
                by_sid[key] = val
        return False

    def workload_shift():
        before = population_counts("before")
        after = population_counts("after")
        classes = set(before) | set(after)
        total_before = sum(before.values())
        total_after = sum(after.values())
        if total_before == 0 or total_after == 0:
            return False
        for cls in classes:
            if abs(before.get(cls, 0) / total_before - after.get(cls, 0) / total_after) > 1e-8:
                return True
        return False

    def incomplete_coverage():
        for period in ("before", "after"):
            obs = observed_counts(period)
            pop = population_counts(period)
            for cls in set(obs) | set(pop):
                if obs.get(cls, 0) != pop.get(cls, 0):
                    return True
        return False

    def unknown_clock_unit():
        units = context.get("clock_units", {})
        for period in ("before", "after"):
            unit = units.get(period)
            if unit is None or str(unit).strip().lower() in ("", "unknown", "none"):
                return True
        return False

    def unit_scale(unit):
        u = str(unit).strip().lower()
        if u in ("second", "seconds", "s"):
            return 1.0
        if u in ("millisecond", "milliseconds", "ms"):
            return 0.001
        if u in ("microsecond", "microseconds", "us"):
            return 0.000001
        if u in ("nanosecond", "nanoseconds", "ns"):
            return 0.000000001
        return 1.0

    findings = []
    unresolved = []

    if duplicate_delivery():
        findings.append("duplicate_delivery")
    if workload_shift():
        findings.append("workload_shift")
    if conflicting_event():
        unresolved.append("conflicting_event")
    if incomplete_coverage():
        unresolved.append("incomplete_coverage")
    if unknown_clock_unit():
        unresolved.append("unknown_clock_unit")

    ratio = None
    if not unresolved:
        units = context.get("clock_units", {})
        before_scale = unit_scale(units.get("before"))
        after_scale = unit_scale(units.get("after"))

        before_reqs = period_requests("before")
        after_reqs = period_requests("after")
        before_pop = population_counts("before")
        after_pop = population_counts("after")

        before_by_class = {}
        for rid, intervals in before_reqs.items():
            cls = request_class("before", rid)
            before_by_class.setdefault(cls, []).append(per_request(intervals) * before_scale)
        after_by_class = {}
        for rid, intervals in after_reqs.items():
            cls = request_class("after", rid)
            after_by_class.setdefault(cls, []).append(per_request(intervals) * after_scale)

        total_before_pop = sum(before_pop.values())
        classes = set(before_pop) | set(after_pop)

        before_std = 0.0
        after_std = 0.0
        for cls in classes:
            w = before_pop.get(cls, 0) / total_before_pop if total_before_pop else 0.0
            bvals = before_by_class.get(cls, [])
            avals = after_by_class.get(cls, [])
            bmean = sum(bvals) / len(bvals) if bvals else 0.0
            amean = sum(avals) / len(avals) if avals else 0.0
            before_std += w * bmean
            after_std += w * amean

        if before_std != 0:
            ratio = after_std / before_std
            if ratio > 1.2 + 1e-8:
                findings.append("latency_regression")
            elif ratio < 0.8 - 1e-8:
                findings.append("latency_improvement")
            else:
                findings.append("latency_stable")
        else:
            unresolved.append("conflicting_event")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}

