        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    per_request = {}
    for row in spans:
        per_request.setdefault((row["period"], row["rid"]), []).append(row)

    class_means = {}
    for period in ("before", "after"):
        for cls in classes:
            vals = []
            for (p, rid), rows in per_request.items():
                if p == period and rows[0]["cohort"] == cls:
                    vals.append(interval_union(rows))
            class_means[(period, cls)] = sum(vals) / len(vals) if vals else 0.0

    before_std = 0.0
    after_std = 0.0
    for cls in classes:
        before_std += before_props[cls] * class_means[("before", cls)]
        after_std += before_props[cls] * class_means[("after", cls)]

    ratio = after_std / before_std if before_std else None

    if ratio is None:
        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    if ratio > 1.2 + 1e-8:
        findings.append("latency_regression")
    elif ratio < 0.8 - 1e-8:
        findings.append("latency_improvement")
    else:
        findings.append("latency_stable")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}
